 $middleware->handle($cashRequest, function () use (&$passed) {
 $passed = true; // si llega aquí, el middleware dejó pasar => sí puede entrar a /cash
 return response('ok');
 });

 return $passed; // false => el middleware redirigiría => sin acceso a caja
 }


