 /**
 * @param array $data
 *
 * @return array
 * @throws \Throwable
 */
 public function storeWithData($data, bool $webExportInvoices = false, bool $deferPdfUntilCommit = false)
 {
 $this->aplicarItineranciaSiCorresponde($data);
 self::setChildrenToData($data);
 $fact = DB::connection('tenant')->transaction(function () use ($data, $webExportInvoices, $deferPdfUntilCommit) {
 $facturalo = new Facturalo();
 if ($webExportInvoices) $facturalo->forWebDocuments();
 $facturalo->save($data);
 if ($deferPdfUntilCommit) {
 DB::connection('tenant')->afterCommit(function () use ($facturalo) {
 try { $facturalo->createPdf(); }
 catch (\Throwable $e) { \Log::warning('No se pudo generar el PDF de la factura de Hotel después del cierre.', ['document_id'=>$facturalo->getDocument()->id, 'error'=>get_class($e)]); }
 });
 } else {
 $facturalo->createPdf();
 }
 return $facturalo;
 });

 $document = $fact->getDocument();
 $response = $fact->getResponse();
 return [
 'success' => true,
 'message' => 'Venta guardada.',
 'data' => [
 'id' => $document->id,
 ...\App\Services\ThirdPartyInvoicePolicy::view($document),
 ...\App\Services\SpecialTaxRegimePolicy::view($document),
 'note_refunds' => \App\Services\Fiscal\NoteRefund::view($document),
 'note_adjustments' => \App\Services\Fiscal\NoteAdjustment::view($document),
 'number_full' => $document->number_full,
 'response' => $response,
 'iva_retention' => \App\Services\Fiscal\IvaRetentionService::view($document),
 'islr_retention' => \App\Services\Fiscal\IslrRetentionService::view($document),
 'fiscal_emission' => \App\Services\Fiscal\DocumentEmissionView::forDocument($document),
 'email_delivery' => \App\Services\Fiscal\HkaMail::view($document),
 'pdf_downloads' => \App\Services\Fiscal\HkaPdf::view($document, false),
 ],
 'links' => [
 'print_ticket' => url('')."/print/document/{$document->external_id}/ticket"
 ]
 ];
 }

 private function associateDispatchesToDocument(Request $request, int $documentId)
 {
 $dispatches_relateds = $request->dispatches_relateds;
 if (!$dispatches_relateds) return;
 $invoice = Document::findOrFail($documentId);
 foreach ($dispatches_relateds as $reference) {
 $parts = \App\Services\Fiscal\FiscalIdentity::parseNumberFull((string) $reference);
 if ($parts === null) continue;
 $dispatch = Dispatch::where('establishment_id', $invoice->establishment_id)
 ->where('fiscal_environment', $invoice->fiscal_environment)
 ->where('document_type_id', '09')
 ->where('series', \App\Services\SeriesNumbering::normalizeCode($parts[0]))
 ->where('number', $parts[1])->first();
 if ($dispatch) {
 $dispatch->update(['reference_document_id' => $documentId]);
 (new Facturalo())->createPdf($dispatch, 'dispatch', 'a4');
 }
 }
 }

