 /**
 * @param \App\Http\Requests\Tenant\DocumentUpdateRequest $request
 * @param $id
 *
 * @return array
 * @throws \Throwable
 */
 public function update(DocumentUpdateRequest $request, $id)
 {

 DocumentFiscalController::authorizeDocument(Document::findOrFail($id));
 $validate = $this->validateDocument($request);
 if (!$validate['success']) return $validate;

 $fact = DB::connection('tenant')->transaction(function () use ($request, $id) {
 $facturalo = (new Facturalo())->forWebDocuments();
 $facturalo->update($request->all(), $id);
 $facturalo->createPdf();

 return $facturalo;
 });

 $document = $fact->getDocument();
 $response = $fact->getResponse();
 $edit = \App\Services\Fiscal\DocumentEditPolicy::view($document);

 return [
 'success' => true,
 'message' => 'Factura actualizada. Los cobros registrados se conservaron. El envío HKA se realiza desde Enviar HKA.',
 'data' => array_merge($edit, \App\Services\ThirdPartyInvoicePolicy::view($document), \App\Services\SpecialTaxRegimePolicy::view($document), [
 'id' => $document->id,
 'is_editable' => $edit['can_edit'],
 'iva_retention' => \App\Services\Fiscal\IvaRetentionService::view($document),
 'islr_retention' => \App\Services\Fiscal\IslrRetentionService::view($document),
 'fiscal_emission' => \App\Services\Fiscal\DocumentEmissionView::forDocument($document),
 'response' => $response,
 ]),
 ];
 }

