 public function preview(DocumentRequest $request)
 {
 $validate = $this->validateDocument($request);
 if (!$validate['success']) return $validate;

 $facturalo = new Facturalo();
 $inputs = $request->all();
 if (!empty($inputs['is_itinerant']) && $inputs['is_itinerant'] === true) {
 if (isset($inputs['customer']['address'])) {
 $inputs['establishment']['address'] = $inputs['customer']['address'];
 $inputs['establishment']['province_id'] = $inputs['customer']['province_id'];
 $inputs['establishment']['province'] = $inputs['customer']['province'];
 $inputs['establishment']['district_id'] = $inputs['customer']['district_id'];
 $inputs['establishment']['district'] = $inputs['customer']['district'];
 $inputs['establishment']['department_id'] = $inputs['customer']['department_id'];
 $inputs['establishment']['department'] = $inputs['customer']['department'];
 }
 }
 $facturalo->setActions(array_key_exists('actions', $inputs) ? $inputs['actions'] : []);

 $document = new Document($inputs);
 $existingDocument = !empty($inputs['id']) ? Document::findOrFail($inputs['id']) : null;
 if ($existingDocument) DocumentFiscalController::authorizeDocument($existingDocument);
 $facturalo->setPaymentsPreview($document, $inputs['payments'], $existingDocument);
 $facturalo->setFeePreview($document, $inputs['fee']);

 foreach ($inputs['items'] as $row) {
 $item = new \App\Models\Tenant\DocumentItem($row);
 $document->items[] = $item;
 }

 if ($inputs['hotel']) {
 $hotel = new \Modules\BusinessTurn\Models\DocumentHotel($inputs['hotel']);
 $document->hotel = $hotel;
 }

 if ($inputs['transport']) {
 $transport = new \Modules\BusinessTurn\Models\DocumentTransport($inputs['transport']);
 $document->transport = $transport;
 }

 $invoice = new \App\Models\Tenant\Invoice($inputs['invoice']);
 $document->invoice = $invoice;

 return $facturalo->previewPdf($document, $inputs['type']);
 }

 }

